import { useState, useCallback, memo, useRef } from "react";

// memo: chỉ render lại khi props thay đổi (so sánh nông)
const Row = memo(function Row({ label, onPick }) {
  const renders = useRef(0);
  renders.current += 1;                                  // đếm số lần render để quan sát
  return <li><button onClick={() => onPick(label)}>{label}</button> <small>render #{renders.current}</small></li>;
});

export default function App() {
  const [count, setCount] = useState(0);
  const [picked, setPicked] = useState("");
  const onPick = useCallback((label) => setPicked(label), []);    // tham chiếu hàm ổn định

  return (
    <div>
      <button id="inc" onClick={() => setCount(count + 1)}>Đếm: {count}</button>
      <p id="picked">{picked}</p>
      <ul><Row label="A" onPick={onPick} /><Row label="B" onPick={onPick} /></ul>
    </div>
  );
}

