import { useState } from "react";

export default function App() {
  const [items, setItems] = useState([{ id: "a", name: "A" }, { id: "b", name: "B" }]);
  return (
    <div>
      <button id="del-first" onClick={() => setItems(items.slice(1))}>Xoá đầu</button>
      <ul>
        {items.map((item) => (
          <li key={item.id} data-name={item.name}><input defaultValue={item.name + "-text"} /></li>
        ))}
      </ul>
    </div>
  );
}
